  -- Global Community Chat — начальные данные (Бишкек).
  -- Сгенерировано из данных frontend-прототипа (src/mocks) один раз; после применения
  -- источником истины становится база. Повторный запуск ничего не дублирует (on conflict do nothing).

  -- ── Города и районы ──
  on conflict (id) do nothing;

  on conflict (id) do nothing;

  -- ── Учебные заведения (123) ──
  on conflict (district_id, id) do nothing;

  -- ── Сообщество города и его каналы ──
  on conflict (id) do nothing;

  on conflict (community_id, name) do nothing;

  -- ── Чаты по месту (145): общий, город, районы, учебные заведения ──
  -- Чтобы добавить чат — добавьте строку в таблицу chats (см. README), код менять не нужно.
  -- Автоматически созданный чат (триггер справочника) получает название и описание из начальных данных
  on conflict (id) do update set name = excluded.name, description = excluded.description, emoji = excluded.emoji;

  -- ── Локальные чаты раздела «Рядом» ──
  on conflict (id) do nothing;

  -- ── Мероприятия (организатор не указан — это демо-данные) ──
  on conflict (id) do nothing;

