    (md5('seed-event-1')::uuid, 'bishkek', 'Футбольный матч во дворе', 'Дружеский матч между классами. Приходите поддержать свою команду!', '⚽', now() + interval '6084 minutes', 'Спортивная площадка, корп. 2', 22),
