    (md5('seed-event-3')::uuid, 'bishkek', 'Осенний концерт', 'Концерт самодеятельности. Выступают ученики 5–11 классов. Приглашаем всех!', '🎭', now() + interval '14844 minutes', 'Актовый зал', null),
