  insert into public.messages (id, chat_id, channel_id, type, content, reply_to_id, created_at) values
    (md5('seed-message-g1')::uuid, null, (select id from public.channels where community_id = 'bishkek' and name = 'general'), 'text', 'Доброе утро, Бишкек! Желаю всем продуктивного дня 🌅', null, now() - interval '156 minutes'),
    (md5('seed-message-g-sys1')::uuid, null, (select id from public.channels where community_id = 'bishkek' and name = 'general'), 'system', '✨ В сообщество вступил новый участник', null, now() - interval '111 minutes'),
    (md5('seed-message-g2')::uuid, null, (select id from public.channels where community_id = 'bishkek' and name = 'general'), 'text', 'Всем привет! Рад быть здесь 🙂', null, now() - interval '110 minutes'),
    (md5('seed-message-g3')::uuid, null, (select id from public.channels where community_id = 'bishkek' and name = 'general'), 'text', 'Привет! Добро пожаловать 👋', null, now() - interval '108 minutes'),
    (md5('seed-message-g4')::uuid, null, (select id from public.channels where community_id = 'bishkek' and name = 'general'), 'text', 'Эй, кто придёт на тренировку сегодня в 16:00? Нам нужен ещё один игрок ⚽', null, now() - interval '84 minutes'),
    (md5('seed-message-g5')::uuid, null, (select id from public.channels where community_id = 'bishkek' and name = 'general'), 'text', 'Я не играю в футбол, но могу поболеть 😄', md5('seed-message-g4')::uuid, now() - interval '81 minutes'),
    (md5('seed-message-g6')::uuid, null, (select id from public.channels where community_id = 'bishkek' and name = 'general'), 'text', 'Я приду! И сфотографирую для школьной газеты 📸', null, now() - interval '79 minutes'),
    (md5('seed-message-g7')::uuid, null, (select id from public.channels where community_id = 'bishkek' and name = 'general'), 'text', 'Кто сегодня идёт в библиотеку после уроков?', null, now() - interval '54 minutes'),
