    (md5('seed-message-g10')::uuid, null, (select id from public.channels where community_id = 'bishkek' and name = 'general'), 'text', 'Тоже приду! У меня доклад по биологии на завтра 😅', null, now() - interval '44 minutes'),
    (md5('seed-message-g11')::uuid, null, (select id from public.channels where community_id = 'bishkek' and name = 'general'), 'text', 'Ребята, напоминаю — завтра контрольная по математике в 9–11 классах. Не забудьте взять калькуляторы!', null, now() - interval '21 minutes'),
